const LANGS: ModuleLanguage[] = ['pt', 'en', 'es', 'fr', 'it', 'ru'];

function build(rows: Record<string, Row>): ModuleTranslations {
  const out = { pt: {}, en: {}, es: {}, fr: {}, it: {}, ru: {} } as ModuleTranslations;
  for (const [key, values] of Object.entries(rows)) {
    LANGS.forEach((lang, i) => {
      out[lang][key] = values[i];
    });
  }
  return out;
}

export const legalMisc: ModuleTranslations = build(ROWS);
